  +  sim.addPlayer('peer-a', 0);
  +  const before = sim.getPlayerSnapshot('peer-a').state;
  +  sim.setPlayerInput('peer-a', {
  +    moveX: 1,
  +    moveY: 0,
  +    aimX: 1,
