    float: (a = 0, b = 1) => rngFloat(gen, a, b),
    int: (a, b) => rngInt(gen, a, b),
    choice: (arr) => rngChoice(gen, arr),
    shuffle: (arr) => rngShuffle(gen, arr),
    shuffleInPlace: (arr) => rngShuffleInPlace(gen, arr),
