      // Generate two uniforms in (0,1]
      let u = 0, v = 0;
      // Avoid u==0 to prevent log(0)
      do { u = gen(); } while (u === 0);
      v = gen();
      const mag = Math.sqrt(-2.0 * Math.log(u));
      const z0 = mag * Math.cos(2 * Math.PI * v);
