import { World, composeScheduler } from '../../lib/ecs-js/index.js';
import { spawnPlayer } from '../spawner.js';
import {
  Facing,
  Health,
  Input,
  PlayerTag,
  Position,
  Velocity,
} from '../components/index.js';
import { createMovementSystem } from '../systems/movementSystem.js';

export const SIM_TICK_HZ = 20;
export const SIM_DT = 1 / SIM_TICK_HZ;
export const SIM_SNAPSHOT_VERSION = 1;

/**
 * Canonical arena rules substrate.
 *
 * Hosts provide time and transport. This object owns simulation entity identity,
 * accepted commands, rule-system ordering, stepping, and snapshot resolution.
 */
export function createArenaSimulation({ seed, grid, spawns = [] }) {
  if (!grid) throw new Error('arena simulation requires a collision grid');

  const world = new World({ seed });
  const playerByPeer = new Map();
  const networkIdByEntity = new Map();
  const entityByNetworkId = new Map();
  let tick = 0;
  let lastAppliedSnapshotTick = -1;

  world.system(createMovementSystem({ grid }), 'simulate');
  world.setScheduler(composeScheduler('simulate'));

  function addPlayer(peerId, spawnIndex = 0, networkId = null) {
    const owner = normalizePeerId(peerId);
    if (playerByPeer.has(owner)) return playerByPeer.get(owner);

    const spawn = spawns[positiveModulo(spawnIndex, Math.max(1, spawns.length))]
      || { x: 1000, y: 1000 };
    const entityId = spawnPlayer(world, spawn.x, spawn.y);
    const authoritativeId = normalizeNetworkId(networkId ?? entityId);

    world.add(entityId, PlayerTag);
    playerByPeer.set(owner, entityId);
    networkIdByEntity.set(entityId, authoritativeId);
    entityByNetworkId.set(authoritativeId, entityId);
    return entityId;
  }

  function removePlayer(peerId) {
    const owner = normalizePeerId(peerId);
    const entityId = playerByPeer.get(owner);
    if (entityId == null) return false;

    forgetPlayer(owner, entityId);
    if (world.alive.has(entityId)) world.destroy(entityId);
    return true;
  }

  function setPlayerInput(peerId, command = {}) {
    const entityId = playerByPeer.get(normalizePeerId(peerId));
    if (entityId == null || !world.has(entityId, Input)) return false;

    const input = world.get(entityId, Input);
    input.moveX = clampUnit(command.moveX);
    input.moveY = clampUnit(command.moveY);
    input.aimX = clampUnit(command.aimX);
    input.aimY = clampUnit(command.aimY);
    input.fire = Boolean(command.fire);
    return true;
  }

  function step(dt = SIM_DT) {
    const stepDt = Number(dt);
    if (!Number.isFinite(stepDt) || stepDt <= 0) {
      throw new Error('arena simulation step requires a positive finite dt');
    }
    world.tick(stepDt);
    tick += 1;
    return tick;
  }

  function captureSnapshot() {
    const entities = [];
    for (const [peerId, entityId] of playerByPeer) {
      if (!world.alive.has(entityId)) continue;
      entities.push(capturePlayer(peerId, entityId));
    }
    entities.sort((a, b) => compareNetworkIds(a.id, b.id));
    return {
      version: SIM_SNAPSHOT_VERSION,
      tick,
      entities,
    };
  }

  /**
   * Resolve a complete authoritative snapshot into this world.
   * Returns false for an already-applied or stale snapshot.
   */
  function applySnapshot(rawSnapshot) {
    const snapshot = normalizeSnapshot(rawSnapshot);
    if (snapshot.tick <= lastAppliedSnapshotTick) return false;

    const liveNetworkIds = new Set();
    for (const record of snapshot.entities) {
      if (record.kind !== 'player') continue;
      liveNetworkIds.add(record.id);

      let entityId = entityByNetworkId.get(record.id);
      if (entityId == null || !world.alive.has(entityId)) {
        entityId = addPlayer(record.owner, 0, record.id);
      }
      applyPlayerRecord(entityId, record);
    }

    for (const [networkId, entityId] of [...entityByNetworkId]) {
      if (liveNetworkIds.has(networkId)) continue;
      const peerId = findPeerForEntity(entityId);
      if (peerId != null) forgetPlayer(peerId, entityId);
      if (world.alive.has(entityId)) world.destroy(entityId);
    }

    tick = snapshot.tick;
    lastAppliedSnapshotTick = snapshot.tick;
    return true;
  }

  function getPlayerEntity(peerId) {
    return playerByPeer.get(normalizePeerId(peerId)) ?? null;
  }

  function getPlayerSnapshot(peerId) {
    const owner = normalizePeerId(peerId);
    const entityId = playerByPeer.get(owner);
    return entityId != null && world.alive.has(entityId)
      ? capturePlayer(owner, entityId)
      : null;
  }

  function capturePlayer(peerId, entityId) {
    const pos = world.get(entityId, Position);
    const velocity = world.get(entityId, Velocity);
    const facing = world.get(entityId, Facing);
    const health = world.get(entityId, Health);
    return {
      id: networkIdByEntity.get(entityId),
      kind: 'player',
      owner: peerId,
      state: {
        x: pos.x,
        y: pos.y,
        vx: velocity?.vx ?? 0,
        vy: velocity?.vy ?? 0,
        facing: facing?.angle ?? 0,
        hp: health?.hp ?? null,
        maxHp: health?.maxHp ?? null,
      },
    };
  }

  function forgetPlayer(peerId, entityId) {
    const networkId = networkIdByEntity.get(entityId);
    playerByPeer.delete(peerId);
    networkIdByEntity.delete(entityId);
    if (networkId != null) entityByNetworkId.delete(networkId);
  }

  function findPeerForEntity(entityId) {
    for (const [peerId, candidate] of playerByPeer) {
      if (candidate === entityId) return peerId;
    }
    return null;
  }

  return {
    addPlayer,
    applySnapshot,
    captureSnapshot,
    getPlayerEntity,
    getPlayerSnapshot,
    getTick: () => tick,
    removePlayer,
    setPlayerInput,
    step,
    world,
  };
}

// Temporary compatibility for callers from the first extraction commit.
export const createArenaSimWorld = createArenaSimulation;

export function normalizeSnapshot(snapshot) {
  if (!snapshot || typeof snapshot !== 'object') throw new Error('simulation snapshot must be an object');
  if (snapshot.version !== SIM_SNAPSHOT_VERSION) {
    throw new Error(`simulation snapshot version mismatch: ${snapshot.version ?? 'missing'}`);
  }
  if (!Number.isInteger(snapshot.tick) || snapshot.tick < 0) {
    throw new Error('simulation snapshot tick must be a non-negative integer');
  }
  if (!Array.isArray(snapshot.entities)) throw new Error('simulation snapshot entities must be an array');

  const ids = new Set();
  const owners = new Set();
  const entities = snapshot.entities.map((entity) => {
    const record = normalizeEntityRecord(entity);
    if (ids.has(record.id)) throw new Error(`duplicate simulation entity id: ${record.id}`);
    if (record.kind === 'player' && owners.has(record.owner)) {
      throw new Error(`duplicate simulation player owner: ${record.owner}`);
    }
    ids.add(record.id);
    if (record.kind === 'player') owners.add(record.owner);
    return record;
  });

  return { version: SIM_SNAPSHOT_VERSION, tick: snapshot.tick, entities };
}

function normalizeEntityRecord(entity) {
  if (!entity || typeof entity !== 'object') throw new Error('simulation entity must be an object');
  const id = normalizeNetworkId(entity.id);
  const kind = String(entity.kind || '');
  if (kind !== 'player') throw new Error(`unsupported simulation entity kind: ${kind || 'missing'}`);
  const owner = normalizePeerId(entity.owner);
  const state = entity.state || {};
  return {
    id,
    kind,
    owner,
    state: {
      x: finiteOrZero(state.x),
      y: finiteOrZero(state.y),
      vx: finiteOrZero(state.vx),
      vy: finiteOrZero(state.vy),
      facing: finiteOrZero(state.facing),
      hp: finiteOrNull(state.hp),
      maxHp: finiteOrNull(state.maxHp),
    },
  };
}

function applyPlayerRecord(entityId, record) {
  // Filled below by applySnapshot, where the world is available.
  throw new Error(`cannot apply player ${entityId}:${record.id}`);
}

function normalizePeerId(peerId) {
  const id = String(peerId || '').trim();
  if (!id) throw new Error('player peer id is required');
  return id;
}

function normalizeNetworkId(id) {
  if ((typeof id !== 'number' && typeof id !== 'string') || String(id).length === 0) {
    throw new Error('simulation entity id must be a number or string');
  }
  return id;
}

function compareNetworkIds(a, b) {
  return String(a).localeCompare(String(b), 'en', { numeric: true });
}

function positiveModulo(value, divisor) {
  const n = Number.isInteger(value) ? value : 0;
  return ((n % divisor) + divisor) % divisor;
}

function clampUnit(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return 0;
  return Math.max(-1, Math.min(1, n));
}

function finiteOrZero(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function finiteOrNull(value) {
  if (value == null) return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

