import {
  DEFAULT_ROOM_ID,
  MESSAGE,
  decodeMessage,
  encodeMessage,
  makeInputFrame,
  normalizeSeed,
  normalizeRoomId,
} from './index.js';
import { normalizeSnapshot } from '../rules/sim/arenaSim.js';

export function createNetClient({
  roomId = DEFAULT_ROOM_ID,
  sendHz = 15,
} = {}) {
  const peers = new Map();
  const minSendMs = 1000 / Math.max(1, sendHz);
  let socket = null;
  let peerId = null;
  let status = 'idle';
  let statusDetail = '';
  let seq = 0;
  let lastSendAt = 0;
  let room = normalizeRoomId(roomId);
  let welcome = null;
  let connectPromise = null;
  let resolveConnect = null;
  let latestSnapshot = null;

  async function connect() {
    if (!('WebSocket' in globalThis)) {
      setStatus('offline', 'websocket unavailable');
      return null;
    }
    if (welcome) return welcome;
    if (connectPromise) return connectPromise;
    if (socket && (socket.readyState === WebSocket.OPEN || socket.readyState === WebSocket.CONNECTING)) return null;

    setStatus('connecting', room);
    try {
      const url = new URL('/api/rooms/default', location.href);
      url.searchParams.set('room', room);
      const response = await fetch(url);
      if (!response.ok) throw new Error(`room lookup failed: ${response.status}`);
      const info = await response.json();
      socket = new WebSocket(info.ws);
      connectPromise = new Promise((resolve) => {
        resolveConnect = resolve;
      });

      socket.addEventListener('open', () => {
        setStatus('joining', room);
        send(MESSAGE.HELLO, {});
      });
      socket.addEventListener('message', (event) => {
        handleMessage(event.data);
      });
      socket.addEventListener('close', () => {
        socket = null;
        peers.clear();
        setStatus('offline', 'socket closed');
        resolveWelcome(null);
      });
      socket.addEventListener('error', () => {
        setStatus('error', 'socket error');
        resolveWelcome(null);
      });
      return connectPromise;
    } catch (err) {
      socket = null;
      peers.clear();
      setStatus('offline', err.message);
      resolveWelcome(null);
      return null;
    }
  }

  function update(tick, sampledInput) {
    const now = performance.now();
    if (!socket || socket.readyState !== WebSocket.OPEN || now - lastSendAt < minSendMs) return;
    lastSendAt = now;
    send(MESSAGE.INPUT, {
      input: makeInputFrame({
        seq: ++seq,
        tick,
        moveX: sampledInput?.intent?.moveX,
        moveY: sampledInput?.intent?.moveY,
        aimX: sampledInput?.intent?.aimX,
        aimY: sampledInput?.intent?.aimY,
        fire: sampledInput?.intent?.fire,
        spellSlot: sampledInput?.spellSlot,
      }),
    });
  }

  function handleMessage(raw) {
    let msg;
    try {
      msg = decodeMessage(raw);
    } catch (err) {
      setStatus('error', err.message);
      return;
    }

    if (msg.type === MESSAGE.WELCOME) {
      peerId = msg.peerId;
      welcome = {
        ...msg,
        seed: normalizeSeed(msg.seed),
        roomId: normalizeRoomId(msg.roomId || room),
        snapshot: acceptSnapshot(msg.snapshot),
      };
      room = welcome.roomId;
      applyPeerList(msg.peers);
      setStatus('connected', room);
      resolveWelcome(welcome);
      return;
    }

    if (msg.type === MESSAGE.SNAPSHOT) {
      acceptSnapshot(msg.snapshot);
      return;
    }

    if (msg.type === MESSAGE.PEER_JOINED) {
      applyPeerList(msg.peers);
      return;
    }

    if (msg.type === MESSAGE.PEER_LEFT) {
      if (msg.peerId) peers.delete(msg.peerId);
      applyPeerList(msg.peers);
      return;
    }

    if (msg.type === MESSAGE.ERROR) {
      setStatus('error', msg.error || 'server error');
    }
  }

  function applyPeerList(peerList = []) {
    const live = new Set();
    for (const peer of peerList) {
      if (!peer?.id) continue;
      live.add(peer.id);
      peers.set(peer.id, {
        id: peer.id,
        joinedAt: peer.joinedAt,
        lastSeenAt: peer.lastSeenAt,
      });
    }
    for (const id of peers.keys()) {
      if (!live.has(id)) peers.delete(id);
    }
  }

  function getRemotePeers() {
    return [...peers.values()].filter((peer) => peer.id !== peerId);
  }

  function getLocalPeer() {
    return peerId ? peers.get(peerId) || null : null;
  }

  function getStatusText() {
    const remoteCount = getRemotePeers().length;
    if (status === 'connected') return `net:${room} seed:${welcome?.seed?.toString(16) || '-'} peers:${remoteCount}`;
    return `net:${status}${statusDetail ? ' ' + statusDetail : ''}`;
  }

  function getSeed() {
    return welcome?.seed ?? null;
  }

  function getLatestSnapshot() {
    return latestSnapshot;
  }

  function acceptSnapshot(snapshot) {
    if (!snapshot) return latestSnapshot;
    try {
      const normalized = normalizeSnapshot(snapshot);
      if (!latestSnapshot || normalized.tick > latestSnapshot.tick) latestSnapshot = normalized;
    } catch (err) {
      setStatus('error', err.message);
    }
    return latestSnapshot;
  }

  function send(type, payload) {
    if (!socket || socket.readyState !== WebSocket.OPEN) return;
    socket.send(encodeMessage(type, payload));
  }

  function setStatus(next, detail = '') {
    status = next;
    statusDetail = detail;
  }

  function resolveWelcome(value) {
    if (!resolveConnect) return;
    const resolve = resolveConnect;
    resolveConnect = null;
    connectPromise = null;
    resolve(value);
  }

  function destroy() {
    if (socket) socket.close();
    socket = null;
    peers.clear();
    latestSnapshot = null;
  }

  return {
    connect,
    destroy,
    getLocalPeer,
    getLatestSnapshot,
    getRemotePeers,
    getSeed,
    getStatusText,
    update,
  };
}
import {
  DEFAULT_ROOM_ID,
  MESSAGE,
  decodeMessage,
  encodeMessage,
  makeInputFrame,
  makeRoomSeed,
  normalizeRoomId,
} from '../public/src/shared/net/protocol.js';
import { generateCave, CaveProfile } from '../public/src/rules/geometry/caveGen.js';
import {
  SIM_DT,
  SIM_TICK_HZ,
  createArenaSimulation,
} from '../public/src/rules/sim/arenaSim.js';

const JSON_HEADERS = {
  'content-type': 'application/json; charset=utf-8',
  'cache-control': 'no-store',
};

const SNAPSHOT_HZ = 10;
const SERVER_TICK_MS = 1000 / SIM_TICK_HZ;
const SNAPSHOT_EVERY_TICKS = Math.max(1, Math.round(SIM_TICK_HZ / SNAPSHOT_HZ));

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === '/api/health') {
      return json({
        ok: true,
        service: 'js-hack-arena',
        runtime: 'cloudflare-worker',
      });
    }

    if (url.pathname === '/api/rooms/default') {
      const roomId = normalizeRoomId(url.searchParams.get('room') || DEFAULT_ROOM_ID);
      return json({
        roomId,
        seed: makeRoomSeed(roomId),
        ws: websocketUrl(request, `/ws/${roomId}`),
      });
    }

    if (url.pathname.startsWith('/ws/')) {
      const roomId = normalizeRoomId(url.pathname.slice('/ws/'.length));
      const id = env.GAME_ROOM.idFromName(roomId);
      return env.GAME_ROOM.get(id).fetch(request);
    }

    return env.ASSETS.fetch(request);
  },
};

export class GameRoom {
  constructor(state, env) {
    this.state = state;
    this.env = env;
    this.sessions = new Map();
    this.tick = 0;
    this.createdAt = Date.now();
    this.roomId = DEFAULT_ROOM_ID;
    this.seed = makeRoomSeed(this.roomId);
    this.caveData = null;
    this.sim = null;
    this.tickTimer = null;
  }

  async fetch(request) {
    const url = new URL(request.url);
    this.setRoomId(normalizeRoomId(url.pathname.startsWith('/ws/') ? url.pathname.slice('/ws/'.length) : DEFAULT_ROOM_ID));

    if (request.headers.get('upgrade') !== 'websocket') {
      return json({
        ok: true,
        roomId: this.roomId,
        room: this.state.id.toString(),
        seed: this.seed,
        peers: this.sessions.size,
        tick: this.tick,
        tickHz: SIM_TICK_HZ,
        snapshotHz: SNAPSHOT_HZ,
      });
    }

    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    this.accept(server);

    return new Response(null, {
      status: 101,
      webSocket: client,
    });
  }

  accept(socket) {
    socket.accept();

    const peerId = crypto.randomUUID();
    const session = {
      id: peerId,
      socket,
      joinedAt: Date.now(),
      lastSeenAt: Date.now(),
      input: makeInputFrame(),
    };

    this.ensureSim().addPlayer(peerId, this.sessions.size);
    this.sessions.set(socket, session);
    this.startTicking();
    this.send(socket, MESSAGE.WELCOME, {
      peerId,
      roomId: this.roomId,
      seed: this.seed,
      tick: this.tick,
      tickHz: SIM_TICK_HZ,
      snapshotHz: SNAPSHOT_HZ,
      peers: this.peerList(),
      snapshot: this.ensureSim().captureSnapshot(),
    });
    this.broadcast(MESSAGE.PEER_JOINED, { peerId, peers: this.peerList() }, socket);

    socket.addEventListener('message', (event) => {
      this.handleMessage(socket, event.data);
    });
    socket.addEventListener('close', () => {
      this.leave(socket);
    });
    socket.addEventListener('error', () => {
      this.leave(socket);
    });
  }

  handleMessage(socket, raw) {
    const session = this.sessions.get(socket);
    if (!session) return;

    let msg;
    try {
      msg = decodeMessage(raw);
    } catch (err) {
      this.send(socket, MESSAGE.ERROR, { error: err.message });
      return;
    }

    session.lastSeenAt = Date.now();

    if (msg.type === MESSAGE.PING) {
      this.send(socket, MESSAGE.PONG, { tick: this.tick });
      return;
    }

    if (msg.type === MESSAGE.HELLO) {
      this.send(socket, MESSAGE.WELCOME, {
        peerId: session.id,
        roomId: this.roomId,
        seed: this.seed,
        tick: this.tick,
        tickHz: SIM_TICK_HZ,
        snapshotHz: SNAPSHOT_HZ,
        peers: this.peerList(),
        snapshot: this.ensureSim().captureSnapshot(),
      });
      return;
    }

    if (msg.type === MESSAGE.INPUT) {
      session.input = makeInputFrame(msg.input);
      this.ensureSim().setPlayerInput(session.id, session.input);
      return;
    }

    this.send(socket, MESSAGE.ERROR, { error: `unsupported message type: ${msg.type}` });
  }

  step() {
    this.tick += 1;
    this.ensureSim().step(SIM_DT);

    if (this.tick % SNAPSHOT_EVERY_TICKS !== 0) return;
    this.broadcast(MESSAGE.SNAPSHOT, {
      snapshot: this.ensureSim().captureSnapshot(),
    });
  }

  leave(socket) {
    const session = this.sessions.get(socket);
    if (!session) return;
    this.sessions.delete(socket);
    this.ensureSim().removePlayer(session.id);
    this.broadcast(MESSAGE.PEER_LEFT, {
      peerId: session.id,
      peers: this.peerList(),
    });
    if (this.sessions.size === 0) this.stopTicking();
  }

  peerList() {
    return [...this.sessions.values()].map((session) => ({
      id: session.id,
      joinedAt: session.joinedAt,
      lastSeenAt: session.lastSeenAt,
    }));
  }

  setRoomId(roomId) {
    if (this.roomId === roomId) return;
    this.roomId = roomId;
    this.seed = makeRoomSeed(roomId);
    this.caveData = null;
    this.sim = null;
  }

  ensureCave() {
    if (!this.caveData) {
      this.caveData = generateCave({
        seed: this.seed,
        width: 2000,
        height: 2000,
        profile: CaveProfile.CAVERNS,
        spawnCount: 4,
      });
    }
    return this.caveData;
  }

  ensureSim() {
    if (!this.sim) {
      const caveData = this.ensureCave();
      this.sim = createArenaSimulation({
        seed: this.seed,
        grid: caveData.grid,
        spawns: caveData.spawns,
      });
    }
    return this.sim;
  }

  startTicking() {
    if (this.tickTimer !== null) return;
    this.tickTimer = setTimeout(() => this.tickLoop(), SERVER_TICK_MS);
  }

  stopTicking() {
    if (this.tickTimer === null) return;
    clearTimeout(this.tickTimer);
    this.tickTimer = null;
  }

  tickLoop() {
    this.tickTimer = null;
    if (this.sessions.size === 0) return;

    try {
      this.step();
    } finally {
      if (this.sessions.size > 0) this.startTicking();
    }
  }

  send(socket, type, payload) {
    if (socket.readyState !== WebSocket.OPEN) return;
    socket.send(encodeMessage(type, payload));
  }

  broadcast(type, payload, except = null) {
    for (const socket of this.sessions.keys()) {
      if (socket !== except) this.send(socket, type, payload);
    }
  }
}

function websocketUrl(request, pathname) {
  const url = new URL(request.url);
  url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
  url.pathname = pathname;
  url.search = '';
  return url.toString();

