--- 1 ---
// display/renderer.js
// Main frame renderer — queries ECS world, draws everything.
// No simulation logic. Pure display.

import { Position, Velocity, Collider, Facing, Health, Actor, ActorKind, Projectile, PointLight, Input, GroundItem, ItemInfo, PlayerTag } from '../rules/components/index.js';
import { AI } from '../rules/components/index.js';
import { applyCamera } from './camera/controller.js';

/**
 * @param {object} deps
 * @param {HTMLCanvasElement} deps.canvas
 * @param {CanvasRenderingContext2D} deps.ctx
 * @param {object} deps.cam
 * @param {object} deps.caveBake
 * @param {object} deps.torchPass
 * @param {object} deps.fx — ParticleFX instance
 * @param {object} deps.world
 * @param {object} deps.hud — HUD DOM elements { hud, readL, readR, zoomReadout }
 * @param {object} deps.input — { leftStick, rightStick, keys, keyboardInput }
 * @param {number} deps.SEED
 * @param {object} deps.runtimeEvents
 */
export function createRenderer(deps) {
  const { canvas, ctx, cam, caveBake, torchPass, fx, world, hud, input, SEED, runtimeEvents, boltFx, net, playerId } = deps;
  let lastRenderTime = 0;

  return function renderFrame() {
    const inp = world.get(playerId, Input);
    const pos = world.get(playerId, Position);
    const col = world.get(playerId, Collider);
    const fac = world.get(playerId, Facing);
    if (!inp || !pos || !col || !fac) return;

    const kb = input.keyboardInput();

    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#0b0f12';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    applyCamera(ctx, cam, canvas);
    ctx.drawImage(caveBake.canvas, 0, 0);

    // Draw ground items (potions etc)
    for (const [id, ipos, gi, info] of world.query(Position, GroundItem, ItemInfo)) {
      const t = performance.now() * 0.003;
      const bob = Math.sin(t + id * 2) * 2;  // gentle bob
      ctx.fillStyle = '#ff5080';
      ctx.font = 'bold 18px ui-monospace, monospace';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(info.glyph, ipos.x, ipos.y + bob);
    }

    // Draw player
    ctx.beginPath();
    ctx.arc(pos.x, pos.y, col.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#193447';
    ctx.fill();
    ctx.strokeStyle = '#6fd';
    ctx.lineWidth = 2;
    ctx.stroke();

    ctx.fillStyle = '#cfe8ff';
    ctx.font = `bold ${Math.floor(col.radius * 1.4)}px ui-monospace, monospace`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('@', pos.x, pos.y + 1);

    // Torch glyph offset from player
    ctx.fillStyle = '#ffbe60';
    ctx.font = 'bold 14px ui-monospace, monospace';
    ctx.fillText('\u2020', pos.x + col.radius + 4, pos.y - col.radius + 2);

    // Remote players are snapshot-resolved ECS entities, just like the local player.
    for (const [id, rpos, rcol, rfac] of world.query(PlayerTag, Position, Collider, Facing)) {
      if (id === playerId) continue;

        ctx.beginPath();
        ctx.arc(rpos.x, rpos.y, rcol.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(30,80,120,0.72)';
        ctx.fill();
        ctx.strokeStyle = 'rgba(130,220,255,0.9)';
        ctx.lineWidth = 2;
        ctx.stroke();

        ctx.fillStyle = 'rgba(215,245,255,0.95)';
        ctx.font = `bold ${Math.floor(rcol.radius * 1.4)}px ui-monospace, monospace`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText('@', rpos.x, rpos.y + 1);

        const angle = rfac.angle;
        const aimLen = rcol.radius + 12;
        ctx.beginPath();
        ctx.moveTo(rpos.x + Math.cos(angle) * rcol.radius, rpos.y + Math.sin(angle) * rcol.radius);
        ctx.lineTo(rpos.x + Math.cos(angle) * aimLen, rpos.y + Math.sin(angle) * aimLen);
        ctx.strokeStyle = 'rgba(140,245,255,0.85)';
        ctx.lineWidth = 2;
        ctx.lineCap = 'round';
        ctx.stroke();
    }

    // Draw mobs
    for (const [id, mpos, mcol, actor, mfac] of world.query(Position, Collider, Actor, Facing)) {
      if (actor.kind !== ActorKind.MOB) continue;
      drawMob(ctx, mpos.x, mpos.y, mcol.radius, mfac.angle, actor.glyph);
    }

    // Draw projectiles
    for (const [id, bpos, vel, proj, bcol] of world.query(Position, Velocity, Projectile, Collider)) {
      const isEnemy = world.has(proj.owner, AI);
      drawProjectile(ctx, bpos.x, bpos.y, vel.vx, vel.vy, bcol.radius, proj.trailColor, isEnemy);
    }

    // Health bars
    for (const [id, hpos, hcol, hp] of world.query(Position, Collider, Health)) {
      if (hp.hp >= hp.maxHp && id !== playerId) continue;
      const ratio = Math.max(0, hp.hp / Math.max(1, hp.maxHp));
      const barW = hcol.radius * 2.2;
      const barH = 4;
      const bx = hpos.x - barW * 0.5;
      const by = hpos.y - hcol.radius - 10;
      const hue = Math.round(120 * ratio);

      ctx.fillStyle = 'rgba(10,12,18,0.8)';
      ctx.fillRect(bx, by, barW, barH);
      if (ratio > 0) {
        ctx.fillStyle = `hsl(${hue} 85% 48%)`;
        ctx.fillRect(bx + 0.5, by + 0.5, (barW - 1) * ratio, barH - 1);
      }
      ctx.strokeStyle = 'rgba(0,0,0,0.85)';
      ctx.lineWidth = 0.5;
      ctx.strokeRect(bx, by, barW, barH);
    }

    // Player aim indicator
    const aimLen = col.radius + 14;
    ctx.beginPath();
    ctx.moveTo(pos.x + Math.cos(fac.angle) * col.radius, pos.y + Math.sin(fac.angle) * col.radius);
    ctx.lineTo(pos.x + Math.cos(fac.angle) * aimLen, pos.y + Math.sin(fac.angle) * aimLen);
    ctx.strokeStyle = '#8fe';
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    ctx.stroke();

    // Lightning bolt FX (world space, additive)
    const now = performance.now() * 0.001;
    const renderDt = lastRenderTime > 0 ? now - lastRenderTime : 0.016;
    lastRenderTime = now;
    if (boltFx) boltFx.render(ctx, renderDt);

    // Torch lighting pass — cap projectile lights for perf
    const lights = [];
    const MAX_PROJ_LIGHTS = 6;
    let projLightCount = 0;
    const t = now;

    for (const [id, lpos, pl] of world.query(Position, PointLight)) {
      if (!pl.enabled) continue;

      // Skip excess projectile lights (small radius = projectile)
      const isProjectileLight = pl.radius <= 130;
      if (isProjectileLight) {
        if (++projLightCount > MAX_PROJ_LIGHTS) continue;
      }

      const isTorch = pl.b < pl.r;
      if (isTorch) {
        const flicker = 1.0
          + 0.12 * Math.sin(t * 5.7 + id)
          + 0.08 * Math.sin(t * 13.3 + id)
          + 0.06 * Math.sin(t * 23.1)
          + 0.10 * (Math.random() - 0.5);
        lights.push({
          x: lpos.x, y: lpos.y,
          radius: pl.radius * Math.max(0.7, flicker),
          color: [
            Math.min(255, pl.r * Math.max(0.8, flicker)),
            Math.min(255, pl.g * Math.max(0.6, flicker * 0.85)),
            Math.min(255, pl.b * Math.max(0.3, flicker * 0.5)),
          ],
        });
      } else {
        const shimmer = 1.0 + 0.05 * Math.sin(t * 20 + id * 7);
        lights.push({

--- 2 ---
import { createTorchPass } from './src/display/passes/torchPass.js';
import { ParticleFX } from './src/display/passes/vfx/particles/particlePool.js';
import { createRenderer } from './src/display/renderer.js';
import { createFloatTextPass } from './src/display/passes/floatText.js';
import { createBoltFx } from './src/display/passes/boltFx.js';
import { spawnCaster, spawnPotion, spawnBow, spawnSword } from './src/rules/spawner.js';
import { Spellbook, Position } from './src/rules/components/index.js';
import { createNetClient } from './src/net/client.js';
import { SIM_TICK_HZ, createArenaSimulation } from './src/rules/sim/arenaSim.js';
import {
  createInputSystem, createAISystem,
  bumpSystem, createProjectileSystem, createDeathSystem, createCameraSystem,
  pickupSystem,
} from './src/rules/systems/index.js';

// ── Canvas + DOM ────────────────────────────────────────────────
const canvas = document.getElementById('game');
const ctx    = canvas.getContext('2d');
function resize() { canvas.width = innerWidth; canvas.height = innerHeight; }
addEventListener('resize', resize); resize();

// -- Ultra-basic multiplayer location sync ----------------------
const roomId = new URLSearchParams(location.search).get('room') || 'lobby';
const netClient = createNetClient({
  roomId,
});
const netWelcome = await netClient.connect();
const isNetworked = Boolean(netWelcome);

// ── Seed + cave ─────────────────────────────────────────────────
const SEED = netWelcome?.seed ?? resolveSeed().seed;
const caveData = generateCave({ seed: SEED, width: 2000, height: 2000, profile: CaveProfile.CAVERNS, spawnCount: 4 });
const { grid, bounds, spawns } = caveData;
const spawn = spawns[0];

// ── Pre-bake display ────────────────────────────────────────────
const caveBake  = bakeCavePass(caveData);
const torchPass = createTorchPass(grid);
const carve     = createCarver(grid, caveBake);

// ── Particle FX ─────────────────────────────────────────────────
const cam = createCamera();
cam.x = cam.targetX = spawn.x;
cam.y = cam.targetY = spawn.y;
cam.scale = cam.targetScale = 1.8;

const fx = new ParticleFX({ capacity: 2048, seedBase: SEED });
fx.worldToScreen = (x, y, size, out) => {
  out.x = (x - cam.x) * cam.scale + canvas.width * 0.5;
  out.y = (y - cam.y) * cam.scale + canvas.height * 0.5;
  out.size = size * cam.scale;
};

// ── Input ───────────────────────────────────────────────────────
const inputRouter = createInputRouter({
  leftBase:    document.getElementById('joystick-left'),
  leftKnob:    document.getElementById('knob-left'),
  leftMarker:  document.getElementById('touch-left'),
  rightBase:   document.getElementById('joystick-right'),
  rightKnob:   document.getElementById('knob-right'),
  rightMarker: document.getElementById('touch-right'),
  canvas,
});

// ── Spell bar (touch) ───────────────────────────────────────────
// Spell bar — intercept touches BEFORE InputRouter claims them
const spellBar = document.getElementById('spell-bar');
spellBar.addEventListener('touchstart', (e) => {
  e.preventDefault();
  e.stopPropagation();
  const btn = e.target.closest('.spell-btn');
  if (!btn) return;
  const slot = Number(btn.dataset.slot);
  inputRouter._setSpellSlot(slot);
  spellBar.querySelectorAll('.spell-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
}, { capture: true });
spellBar.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  e.stopPropagation();
  const btn = e.target.closest('.spell-btn');
  if (!btn) return;
  const slot = Number(btn.dataset.slot);
  inputRouter._setSpellSlot(slot);
  spellBar.querySelectorAll('.spell-btn').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
});

// ── ECS world ───────────────────────────────────────────────────
const sim = createArenaSimulation({ seed: SEED, grid, spawns });
if (isNetworked && netWelcome.snapshot) sim.applySnapshot(netWelcome.snapshot);
const playerId = isNetworked
  ? (sim.getPlayerEntity(netWelcome.peerId) ?? sim.addPlayer(netWelcome.peerId, 0))
  : sim.addPlayer('local', 0);
const world = sim.world;
const runtimeEvents = { casts: 0 };
const initialPlayerPosition = world.get(playerId, Position);
cam.x = cam.targetX = initialPlayerPosition.x;
cam.y = cam.targetY = initialPlayerPosition.y;

// ── Spawn entities ──────────────────────────────────────────────
if (!isNetworked) spawnCaster(world, grid, spawn.x + 200, spawn.y + 150, playerId);

// ── System context (shared deps injected into system closures) ──
const sysCtx = { grid, fx, cam, inputRouter, playerId, carve };

// ── Register systems ────────────────────────────────────────────
if (isNetworked) {
  world.system(createCameraSystem(sysCtx), 'camera');
  world.setScheduler(composeScheduler('camera'));
} else {
  world.system(createInputSystem(sysCtx),      'input');
  world.system(createAISystem(sysCtx),         'simulate');
  world.system(bumpSystem,                     'simulate');
  world.system(pickupSystem,                   'simulate');
  world.system(createProjectileSystem(sysCtx), 'simulate');
  world.system(createDeathSystem(sysCtx),      'simulate');
  world.system(createCameraSystem(sysCtx),     'camera');
  world.setScheduler(composeScheduler('input', 'simulate', 'camera'));
}

// ── Float text (damage numbers) ─────────────────────────────────
const floatText = createFloatTextPass();
world.on('damage.dealt', (e) => {
  const isHeal = e.amount < 0;
  floatText.add({
    x: e.x, y: e.y,
    text: isHeal ? '+' + Math.abs(e.amount) : '-' + e.amount,
    color: isHeal ? '#44ff66' : (e.target === playerId ? '#ff4444' : '#ffcc00'),
  });
});

