import {
  assert,
  assertAlmostEquals,
  assertEquals,
  assertThrows,
} from "https://deno.land/std@0.220.0/assert/mod.ts";
import { Facing, Input, Position } from '../public/src/rules/components/index.js';
import { generateCave, CaveProfile } from '../public/src/rules/geometry/caveGen.js';
import {
  SIM_DT,
  SIM_SNAPSHOT_VERSION,
  createArenaSimulation,
  normalizeSnapshot,
} from '../public/src/rules/sim/arenaSim.js';

function makeCave(seed = 1234) {
  return generateCave({
    seed,
    width: 1000,
    height: 1000,
    profile: CaveProfile.CAVERNS,
    spawnCount: 2,
  });
}

function makeSim(seed = 1234) {
