--- 1 ---
// rules/geometry/carve.js
// Destructible terrain — poke holes in the SDF grid + baked cave canvas.

/**
 * Create a carve function bound to a grid and baked cave canvas.
 *
 * @param {object} grid — { moveGrid, cols, rows, cellSize }
 * @param {{ canvas }} caveBake — the pre-baked cave pass
 * @returns {(wx, wy, radius) => void}
 */
export function createCarver(grid, caveBake) {
  const { moveGrid, cols, rows, cellSize } = grid;
  const bakeCtx = caveBake.canvas.getContext('2d');

  /**
   * Carve a hole in the cave at world position (wx, wy) with given radius.
   * Updates both the collision grid and the visual bake.
   */
  return function carve(wx, wy, radius) {
    const clearance = 40;  // how "open" carved cells become
    const invCell = 1 / cellSize;

    // Grid cells to poke
    const gx0 = Math.max(0, Math.floor((wx - radius) * invCell));
    const gy0 = Math.max(0, Math.floor((wy - radius) * invCell));
    const gx1 = Math.min(cols - 1, Math.ceil((wx + radius) * invCell));
    const gy1 = Math.min(rows - 1, Math.ceil((wy + radius) * invCell));
    const r2 = radius * radius;

    for (let gy = gy0; gy <= gy1; gy++) {
      for (let gx = gx0; gx <= gx1; gx++) {
        const dx = gx * cellSize - wx, dy = gy * cellSize - wy;
        if (dx * dx + dy * dy <= r2) {
          moveGrid[gy * cols + gx] = clearance;
        }
      }
    }

    // Paint floor on the baked canvas
    bakeCtx.beginPath();
    bakeCtx.arc(wx, wy, radius, 0, Math.PI * 2);
    // Edge fringe
    bakeCtx.fillStyle = '#0f1a28';
    bakeCtx.arc(wx, wy, radius + 2, 0, Math.PI * 2);
    bakeCtx.fill();
    // Core floor
    bakeCtx.beginPath();
    bakeCtx.arc(wx, wy, radius, 0, Math.PI * 2);
    bakeCtx.fillStyle = '#142030';
    bakeCtx.fill();
  };
}
// rules/systems/pickupSystem.js — walk over ground items to pick them up.
import { Position, Collider, Health, Input, GroundItem, Consumable, ItemInfo, Spellbook, MeleeWeapon } from '../components/index.js';

export function pickupSystem(world, dt) {
  const players = [];
  for (const [id, pos, col, hp] of world.query(Position, Collider, Health, Input)) {
    players.push({ id, pos, col, hp });
  }

  const toDestroy = [];
  for (const [itemId, ipos, icol, gi] of world.query(Position, Collider, GroundItem)) {
    for (const p of players) {
      const dx = p.pos.x - ipos.x, dy = p.pos.y - ipos.y;
      const dist = Math.hypot(dx, dy);
      // Generous pickup radius — player radius + item radius + 6px grace
      if (dist < p.col.radius + icol.radius + 6) {
        if (world.has(itemId, Consumable)) {
          const c = world.get(itemId, Consumable);
          const info = world.has(itemId, ItemInfo) ? world.get(itemId, ItemInfo) : null;

          if (c.effect === 'heal') {
            p.hp.hp = Math.min(p.hp.maxHp, p.hp.hp + c.potency);
            world.emit('damage.dealt', {
              target: p.id, source: itemId, amount: -c.potency,
              x: p.pos.x, y: p.pos.y,
            });
          } else if (c.effect === 'add_spell' && world.has(p.id, Spellbook)) {
            const book = world.get(p.id, Spellbook);
            const spellId = (info && (info.name === 'Short Bow' || info.name === 'Shadow Longbow' || info.name === 'Sunfire Longbow')) ? 'arrow' : null;
            if (spellId && !book.spells.includes(spellId)) {
              book.spells.push(spellId);
            }
            world.emit('item.pickup', { entity: p.id, item: info?.name, spellId });
          } else if (c.effect === 'melee_upgrade' && world.has(p.id, MeleeWeapon)) {
            const mw = world.get(p.id, MeleeWeapon);
            if (c.potency > mw.damage) {
              mw.damage = c.potency;
              mw.name = info?.name || mw.name;
              mw.glyph = info?.glyph || mw.glyph;
            }
            world.emit('item.pickup', { entity: p.id, item: info?.name });
          } else if (c.effect === 'epic_chest') {
            // Epic chest: emit event so index.html can roll the chest table and spawn loot
            world.emit('chest.opened', { entity: p.id, x: ipos.x, y: ipos.y });
            world.emit('item.pickup', { entity: p.id, item: info?.name });
          }
        }
        toDestroy.push(itemId);
        break;
      }
