/**
 * Pick a weighted random entry from a table.
 */
export function rollTable(table, totalWeight) {
  let roll = Math.random() * totalWeight;
  for (const entry of table) {
    roll -= entry.weight;
    if (roll <= 0) return entry;
  }
  return table[table.length - 1];
}

