+  health.hp = Math.max(0, health.hp - damage);
+  world.emit('damage.dealt', {
+    target: targetId,
+    source: sourceId,
+    amount: damage,
+    x: position.x,
+    y: position.y,
+  });
+}
+
+function positionOf(body) {
+  return body.position;
+}
